    $key = $card + '|' + $ui.View + '|' + $ui.Sent.Text + '|' + $ui.Kick.Text; $ui.LayCards[$key] = 1
    $key += '|' + $ui.Form.ClientSize.Width + 'x' + $ui.Form.ClientSize.Height; if ($ui.LaySeen.ContainsKey($key)) { return }; $ui.LaySeen[$key] = 1
    if ($ui.Scrolls -and -not $ui.RecOn) { $ui.LayScroll[$card] = 1 }
    $todo = New-Object System.Collections.Stack; $todo.Push(@($ui.Form, $ui.Form.RectangleToScreen($ui.Form.ClientRectangle), $false))
    while ($todo.Count) {
      $it = $todo.Pop(); $par = $it[0]; $clip = $it[1]; $scroll = $it[2]
      $kids = @($par.Controls | Where-Object { $_.Visible })
      for ($i = 0; $i -lt $kids.Count; $i++) {
        $c = $kids[$i]; $r = $c.RectangleToScreen($c.ClientRectangle); if ($r.Width -le 0 -or $r.Height -le 0) { continue }
        if (-not $scroll -and -not $clip.Contains($r)) { $ui.LayBad.Add('LAYOUT ' + $card + ' ' + (& $ui.NameOf $c) + ' cut: needs ' + $r.Width + 'x' + $r.Height + ' at ' + ($r.Left - $clip.Left) + ',' + ($r.Top - $clip.Top) + ' in ' + $clip.Width + 'x' + $clip.Height) }
        if ($c -is [System.Windows.Forms.Label] -and $c.AutoSize -and $c.MaximumSize.Width -gt 0 -and $c.Text) { $wb = & $ui.WordBad $card (& $ui.NameOf $c) ([string]$c.Text) $c.Font $c.MaximumSize.Width; if ($wb) { $ui.LayBad.Add($wb) } }
        if (& $ui.IsCardText $c) {   # card text boxes are measured as labels are: a word wider than the line, and text that needs more room than the box has
          if ([int](& $ui.GetWrap $c) -gt 0 -and $c.Text) { $wb = & $ui.WordBad $card (& $ui.NameOf $c) ([string]$c.Text) $c.Font ([int](& $ui.GetWrap $c)); if ($wb) { $ui.LayBad.Add($wb) } }
          $nd = & $ui.TextNeed $c; if ($c.Text -and ($nd.Height -gt $c.ClientSize.Height + 1 -or $nd.Width -gt $c.ClientSize.Width + 1)) { $ui.LayBad.Add('LAYOUT ' + $card + ' ' + (& $ui.NameOf $c) + ' text: needs ' + $nd.Width + 'x' + $nd.Height + ' has ' + $c.ClientSize.Width + 'x' + $c.ClientSize.Height) }
          $lh1 = [int][System.Windows.Forms.TextRenderer]::MeasureText('Ag', $c.Font).Height; if ($c.Text -and $c.ClientSize.Height -gt $nd.Height + $lh1) { $ui.LayBad.Add('LAYOUT ' + $card + ' ' + (& $ui.NameOf $c) + ' dead space: has ' + $c.ClientSize.Height + ' high, the text needs ' + $nd.Height) } }   # more than one empty line under its text
        if ($c -is [System.Windows.Forms.CheckBox] -and $c.Text -and -not $c.AutoEllipsis) {   # a one-line check box whose text alone is wider than it is cut (the Record's step boxes before R24 fix round 3)
          $tw = [System.Windows.Forms.TextRenderer]::MeasureText([string]$c.Text, $c.Font).Width; if ($tw -gt $c.ClientSize.Width + 1) { $ui.LayBad.Add('LAYOUT ' + $card + ' ' + (& $ui.NameOf $c) + ' text cut: needs ' + $tw + ' has ' + $c.ClientSize.Width) } }
        # A cut line (R28 N9: the run card's status line was cut through its middle): a control with text is at least one line of its
        # font tall, also a label that ends with "..." by rule. A rich text box (the lines of a hand step) is as tall as its text.
        if ($c.Text -and ($c -is [System.Windows.Forms.Label] -or $c -is [System.Windows.Forms.ButtonBase] -or $c -is [System.Windows.Forms.TextBoxBase])) {
          $lh = [int][System.Windows.Forms.TextRenderer]::MeasureText('Ag', $c.Font).Height; if ($c -is [System.Windows.Forms.TextBoxBase]) { $lh = [int][math]::Floor($lh * 0.8) }   # an edit control draws a line with less padding
          if ($c.ClientSize.Height + 1 -lt $lh) { $ui.LayBad.Add('LAYOUT ' + $card + ' ' + (& $ui.NameOf $c) + ' line cut: one line needs ' + $lh + ' high, has ' + $c.ClientSize.Height) } }
        if ($c -is [System.Windows.Forms.RichTextBox] -and $ui.GuideNeed -and [object]::ReferenceEquals($c, $ui.Guide)) { $gn = [int](& $ui.GuideNeed); if ($gn -gt $c.ClientSize.Height + 1) { $ui.LayBad.Add('LAYOUT ' + $card + ' Guide text: needs ' + $gn + ' high, has ' + $c.ClientSize.Height) } }
        $isText = ($c -is [System.Windows.Forms.Label] -or $c -is [System.Windows.Forms.ButtonBase])
        if ($isText -and $c.Text -and -not $c.AutoEllipsis) {   # a label or box that ends with "..." by rule is not a defect
          $want = $c.GetPreferredSize((New-Object System.Drawing.Size($c.Width, 0)))
          if ($want.Width -gt $c.Width + 1 -or $want.Height -gt $c.Height + 1) { $ui.LayBad.Add('LAYOUT ' + $card + ' ' + (& $ui.NameOf $c) + ' text: needs ' + $want.Width + 'x' + $want.Height + ' has ' + $c.Width + 'x' + $c.Height) }
        }
        for ($j = $i + 1; $j -lt $kids.Count; $j++) { if ($c.Bounds.IntersectsWith($kids[$j].Bounds)) { $ui.LayBad.Add('LAYOUT ' + $card + ' ' + (& $ui.NameOf $c) + ' overlaps ' + (& $ui.NameOf $kids[$j])) } }
        $sc2 = [bool]$c.AutoScroll; if ([object]::ReferenceEquals($c, $ui.Scroll)) { $sc2 = [bool]$ui.Scrolls }   # the card's text scrolls only when $ui.Squeeze says so
        if ($c.Controls.Count) { $todo.Push(@($c, [System.Drawing.Rectangle]::Intersect($clip, $r), ($scroll -or $sc2))) }
      }
    }
    # Dead space (R28 N9: a large empty area under the run card's text): the card's text panel is as tall as its text when it does not scroll.
    if ($ui.Scroll -and $ui.Body -and -not $ui.RecOn -and -not $ui.Scrolls -and $ui.Scroll.Visible) { $dead = [int]$ui.Scroll.ClientSize.Height - [int]$ui.Body.Height; if ($dead -gt (& $ui.Sc 2)) { $ui.LayBad.Add('LAYOUT ' + $card + ' Scroll dead space: ' + $dead + ' px under the text') } }
    foreach ($l in @(& $ui.Measure $card)) { $ui.LayBad.Add([string]$l) }
  } catch { $ui.LayBad.Add('LAYOUT ' + $card + ' the self-check stopped: ' + (ConvertTo-Masked ([string]$_.Exception.Message))) } }
# <<< rade-ui
# ---- High contrast (R31 W2; R30b check 10: the window kept its own colors when a contrast theme came on)
# With Windows high contrast on, the window paints with the system colors of the theme instead of its own palette.
# The role of each color: backgrounds become Window, text and lines WindowText, muted text GrayText, the action
# Highlight, a button that is not available ButtonFace. The rail turns round: navy (its background) becomes WindowText
# and its light text Window, so it stays readable. One table serves $pc and $ui.C: a hashtable key ignores case, and
# each name the two share (navy, ink, track, white) has one role in both. Yellow fills become Window: dark text on the
# theme's Highlight color can be hard to read.
$ui.HcRole = @{ ink = 'WindowText'; muted = 'GrayText'; surface = 'Window'; line = 'WindowText'; navy = 'WindowText'; onPrimaryMuted = 'Window'
  accentFill = 'Window'; primary = 'Highlight'; track = 'GrayText'; redTint = 'Window'; amberTint = 'Window'; greenTint = 'Window'; white = 'Window'
  blue = 'Highlight'; yellow = 'Window'; green = 'WindowText'; greenInk = 'WindowText'; red = 'WindowText'; gray = 'GrayText'; edge = 'WindowText'
  hair = 'GrayText'; off = 'ButtonFace'; offInk = 'GrayText' }
function Select-T22Color([bool]$High, [hashtable]$Own, [hashtable]$Role) {
  # The colors to paint with: a new table with the keys of $Own. $High false: the colors of $Own. $High true: for each
  # key the system color its role names in $Role (a key with no role gets WindowText, so no text is lost). $Own is not
  # changed. The measure part checks this choice without switching the Windows theme (tests/ps/Test-T22Layout.ps1).
  $out = @{}
  foreach ($k in @($Own.Keys)) {
    if ($High) { $r = [string]$Role[$k]; if (-not $r) { $r = 'WindowText' }; $out[$k] = [System.Drawing.SystemColors]::$r }
    else { $out[$k] = $Own[$k] } }
  return $out
}
# The window's own colors, kept before any change, and whether the system colors are in use.
$ui.OwnPc = $pc.Clone(); $ui.OwnC = $ui.C.Clone(); $ui.High = $false
# Puts the colors for $High into $pc and $ui.C in place (every builder and every paint handler reads them there).
$ui.UseColors = { param([bool]$High)
  $a = Select-T22Color $High $ui.OwnPc $ui.HcRole; foreach ($k in @($a.Keys)) { $pc[$k] = $a[$k] }
  $b = Select-T22Color $High $ui.OwnC $ui.HcRole; foreach ($k in @($b.Keys)) { $ui.C[$k] = $b[$k] }
  $ui.High = $High }
'@ }
# ---- File 5 of 20: T22\90161Z-T22-parts-r6.ps1 (from scripts/gov/90161Z-T22-parts-r6.ps1, sha256 695a183deac1)
$files += @{ Dir = 'T22'; Name = '90161Z-T22-parts-r6.ps1'; Kind = 'text'; Sha = '695a183deac1'; Data = @'
<#
.SYNOPSIS
  90-161.Z Task 22 r6, part "parts": the builders of a card's parts (text, buttons, links, chips, panels, the card
  frame) and of each block type of the card data (chips, headline, text, steps, checks, boxes, rows, lists, filter,
  input, choices, error, progress, buttons).
.DESCRIPTION
  Each builder makes Windows Forms controls with the RADE look ($ui, from the ui part) and adds them to a parent.
  R4 (R30 V3): a format check with 0 findings shows no link (Test-CheckLink, in the cards part). The grid block is
  built by the grid part. R6 (R31b D3): the chip of a check block is level with the first line of its text; the
  helpers $wn.LineH, $wn.PageTop and $wn.TextMid give the text middles that the window, the measure part and the
  layout self-check compare (one rule for D1 to D3).
  Inputs: $ui, $wn, $pc and the card data. Outputs: the $wn members below; nothing is read or saved.
  Run: not alone; 90161Z-T22-pfm-window-r6.ps1 dot-sources it from its own folder inside its try block.
  Network: none.
  Writes: none.
  Credentials: none.
#>
# A size at 100 % in screen pixels (the RADE scale).
$wn.Sc = { param([double]$Px) & $ui.Sc $Px }
# The height of one line of text in font $F, in pixels (as a card text box spaces its lines).
$wn.LineH = { param($F) return [int][Windows.Forms.TextRenderer]::MeasureText('Ag', $F).Height }
# The top of control $C in the pixels of the page (the sum of the tops up to the page), from the layout alone: no handle needed.
$wn.PageTop = { param($C) $y = 0; while ($C -and -not [object]::ReferenceEquals($C, $page)) { $y += $C.Top; $C = $C.Parent }; return $y }
# The vertical middle of the first text line of control $C, in page pixels (R6, D1 to D3). A card text box draws its
# first line at its top: top + one line / 2. A chip or a crumb link draws its text in its vertical middle: top + height / 2.
$wn.TextMid = { param($C)
  if ($C -is [Windows.Forms.TextBox]) { return ((& $wn.PageTop $C) + (& $wn.LineH $C.Font) / 2.0) }
  return ((& $wn.PageTop $C) + $C.Height / 2.0) }
# Adds a card text box (selectable, read-only, no tab stop) with its text, font, color, top gap, wrap width and
# accessible name to $Parent; $Back is its background when it is not white. Gives back the box.
$wn.Txt = { param($Parent, [string]$Text, $Font, $Color, [int]$Top, [int]$W, [string]$Name, $Back)
  $t = & $ui.Text $Font $Color (& $wn.Sc $Top) $Name
  if ($Back) { $t.BackColor = $Back }
  $t.Text = $Text; & $ui.SetWrap $t $W; $t.Visible = $true; [void]$Parent.Controls.Add($t); return $t }
# Rounds the corners of a control ($Rad pixels).
$wn.Round = { param($C, [int]$Rad) try { [Pfm.Gfx]::RoundRegion($C, $Rad) } catch { $null = $_ }; return $null }
# A card button: the RADE action or compact button, blue for the main one, white for the others. $B: Text, Kind, Go, Note, Need.
$wn.Button = { param($B, [string]$Kind)
  $x = & $ui.Btn $Kind
  $x.Text = [string]$B.Text; & $ui.Style $x $(if ($B.Kind -eq 'primary') { 'primary' } else { '' }); $x.AccessibleName = [string]$B.Text; $x.Tag = $B
  $x.Add_SizeChanged({ & $wn.Round $this 4 })
  $x.Add_Click({ & $wn.Press $this.Tag })
  return $x }
# A link of a card (the RADE link button). $B: Text, Go, Note.
$wn.Link = { param($B)
  $x = & $ui.LinkBtn ([string]$B.Text); $x.AccessibleName = [string]$B.Text; $x.Tag = $B
  $x.Add_Click({ & $wn.Press $this.Tag })
  return $x }
# The chip colors by kind: your turn, late, due soon, done, warning, neutral. Read again from $pc when the colors change
# (R31 W2, $wn.Recolor in the window part).
$wn.FillsOf = { return @{ turn = $pc.accentFill; late = $pc.redTint; soon = $pc.amberTint; ok = $pc.greenTint; amber = $pc.amberTint; neu = $pc.surface } }
$wn.Fills = & $wn.FillsOf
# A status chip of kind $Kind with $Text, on background $Back. Gives back the chip.
$wn.Chip = { param($Kind, [string]$Text, $Back)
  $c = New-Object Pfm.Chip; $c.Text = $Text; $c.Font = $ui.F.SmallB; $c.ForeColor = $pc.ink; $c.Fill = $wn.Fills[$Kind]; $c.BackColor = $Back; $c.AccessibleName = $Text
  $w = [Windows.Forms.TextRenderer]::MeasureText($Text, $c.Font).Width + (& $wn.Sc 22)
  $c.Size = [Drawing.Size]::new($w, (& $wn.Sc 26)); $c.Margin = & $ui.Pad 0 0 (& $wn.Sc 8) 0
  return $c }
# A white panel $W wide with a top gap; its children are placed by hand and it draws their focus ring.
$wn.Panel = { param([int]$W, [int]$Top)
  $p = New-Object System.Windows.Forms.Panel; $p.BackColor = $ui.C.White; $p.Size = [Drawing.Size]::new($W, 1); $p.Margin = & $ui.Pad 0 (& $wn.Sc $Top) 0 0
  & $ui.Ring $p; return $p }
# Makes a hand-placed panel as tall as its lowest child plus $Pad.
$wn.Fit = { param($P, [int]$Pad)
  $h = 0; foreach ($c in $P.Controls) { if ($c.Bottom -gt $h) { $h = $c.Bottom } }
  $P.Height = $h + (& $wn.Sc $Pad) }
# A 1 px separator line, $W wide, in $Parent.
$wn.Rule = { param($Parent, [int]$W, [int]$Top)
  $r = New-Object System.Windows.Forms.Panel; $r.BackColor = $pc.line; $r.Size = [Drawing.Size]::new($W, 1); $r.Margin = & $ui.Pad 0 (& $wn.Sc $Top) 0 0; $r.AccessibleName = 'Separator line'
  [void]$Parent.Controls.Add($r) }
# A left-to-right flow in $Parent with background $Back; it draws its children's focus ring. Gives back the flow.
$wn.Flow = { param($Parent, $Back)
  $f = & $ui.Flow 0; $f.BackColor = $Back; $f.Visible = $true; & $ui.Ring $f; [void]$Parent.Controls.Add($f); return $f }
$wn.Card = {
  <#
  .SYNOPSIS
  A card frame: a top-down flow with a thin edge, rounded corners and an optional blue top bar and caption.
  .PARAMETER W
  The card width in pixels (its minimum width; it grows in height with its parts).
  .PARAMETER Cap
  The caption in capitals at the top, or nothing.
  .PARAMETER Top
  When set, a 4 px blue bar at the top (the card that holds the main task).
  .PARAMETER PadX
  The space left and right inside the card, at 100 %.
  .PARAMETER Back
  The color around the rounded corners (the page behind the card).
  .OUTPUTS
  The card (Pfm.Card).
  #>
  param([int]$W, $Cap, $Top, [int]$PadX, $Back)
  $c = New-Object Pfm.Card; $c.FlowDirection = 'TopDown'; $c.WrapContents = $false; $c.AutoSize = $true; $c.AutoSizeMode = 'GrowAndShrink'
  $c.BackColor = $ui.C.White; $c.Outer = $Back; $c.Line = $pc.line; $c.MinimumSize = [Drawing.Size]::new($W, 0)
  $tp = $(if ($Top) { 4 } else { 0 }); if ($Top) { $c.TopFill = $pc.primary; $c.TopH = (& $wn.Sc 4) }
  $c.Padding = & $ui.Pad (& $wn.Sc $PadX) (& $wn.Sc (18 + $tp)) (& $wn.Sc $PadX) (& $wn.Sc 18); $c.Margin = & $ui.Pad 0 0 0 (& $wn.Sc 14)
  & $ui.Ring $c
  if ($Cap) { [void](& $wn.Txt $c (([string]$Cap).ToUpperInvariant()) $ui.F.SmallB $ui.C.Gray 0 ($W - 2 * (& $wn.Sc $PadX)) 'Section' $null) }
  return $c }
# ---- The block builders: one per block type T of the card data. Each takes the parent, the block, the width and the
# column context (@{ Col }; only the grid reads it), and adds its controls to the parent. A builder declares only what it reads.
$wn.Blocks = @{}
# Chips in a row, with the step line in capitals after them.
$wn.Blocks.chips = { param($Parent, $b, [int]$W)
  $f = & $wn.Flow $Parent $ui.C.White; $f.Margin = & $ui.Pad 0 0 0 (& $wn.Sc 10)
  foreach ($it in @($b.Items)) { [void]$f.Controls.Add((& $wn.Chip $it[0] $it[1] $ui.C.White)) }
  if ($b.Cap) { [void](& $wn.Txt $f (([string]$b.Cap).ToUpperInvariant()) $ui.F.SmallB $ui.C.Gray 4 ([math]::Max((& $wn.Sc 200), $W - (& $wn.Sc 260))) 'Step line' $null) } }
# The headline (Small: the body size).
$wn.Blocks.head = { param($Parent, $b, [int]$W)
  $font = $(if ($b.Small) { $ui.F.Body } else { $ui.F.Sent })
  [void](& $wn.Txt $Parent $b.Text $font $ui.C.Navy 4 $W 'Heading' $null) }
# A text: Style box (gray box), note (small gray), cap (a label in capitals) or body text.
$wn.Blocks.p = { param($Parent, $b, [int]$W)
  $st = [string]$b.Style
  if ($st -eq 'box') {
    $bx = & $wn.Panel $W 12; $bx.BackColor = $pc.surface
    $t = & $wn.Txt $bx $b.Text $ui.F.Small $ui.C.Ink 0 ($W - 2 * (& $wn.Sc 12)) 'Note' $pc.surface; $t.Location = [Drawing.Point]::new((& $wn.Sc 12), (& $wn.Sc 10))
    & $wn.Fit $bx 10; [void]$Parent.Controls.Add($bx) }
  elseif ($st -eq 'note') { [void](& $wn.Txt $Parent $b.Text $ui.F.Small $ui.C.Gray 8 $W 'Note' $null) }
  elseif ($st -eq 'cap') { [void](& $wn.Txt $Parent (([string]$b.Text).ToUpperInvariant()) $ui.F.SmallB $ui.C.Gray 14 $W 'Label' $null) }
  else { [void](& $wn.Txt $Parent $b.Text $ui.F.Body $ui.C.Ink 8 $W 'Text' $null) } }
$wn.Blocks.steps = {
  <#
  .SYNOPSIS
