$steps += @{ Name = 'T21 Power Automate shows your connections r6'; Title = 'Check that Power Automate shows your connections'; Dir = 'T21'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You check that Power Automate can show your connections before the flow steps. About 3 minutes.'; Kind = 'guide'; Guide = @('1. Select "Open in browser" above.', '2. If Power Automate asks you to sign in: sign in with your CAC.', '3. On the left, select "Connections" (it can be under "More" or "Data").', '4. Wait until the list of connections shows.', '5. Look in the list for a SharePoint connection.', 'If the page says the connections could not be loaded: wait 5 minutes, then reload the page.', 'If the list still does not show after the reload: select "It failed".', 'In the "It failed" box, type only the line that starts with "Error" (no time stamp or session ID).'); Url = 'https://make.powerautomate.appsplatform.us/'; UrlConfig = '90161Z-flow-portal.txt'; Marker = '90161Z-T21-pa-ready.txt'; Estimate = 180; DoneText = 'The list loaded'; DoneLog = 'Confirmed by you: Power Automate shows the connections.'; Makes = @(); After = @(); Optional = $false; Help = ''; Hide = @('skip'); Answers = @(@{ Key = 'pa-sharepoint'; Prompt = 'Is there a SharePoint connection in the list?'; Kind = 'pick'; Choices = @('Yes', 'No SharePoint connection') }) }
$steps += @{ Name = 'T21 Import the health flow r5: choose the file'; Title = 'Start the import of the health flow'; Dir = 'T21'; File = '90161Z-T21-probe-r5.zip'; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You start the import of the solution "90-161.Z probe health" (1 flow). It now checks only that your own flows are On. The next step finishes it. About 4 minutes.'; Kind = 'guide'; Guide = @('1. Select "Open in browser" above.', '2. If Power Automate asks you to sign in: sign in with your CAC.', '3. On the left, select "Solutions" (it can be under "More").', '4. Select "Import solution".', '5. Select "Browse".', '6. Select the box "File name".', '7. In the box "File name", press Ctrl+V (the file path is on the clipboard).', '8. Select "Open".', '9. Select "Next".', 'If the Open window closes before the file is chosen: select "Browse" again.', 'If the box "File name" is empty after Ctrl+V: press Ctrl+V again.', 'If you see an error: wait 5 minutes, reload the Power Automate page, and try 1 more time.', 'If the page refuses the file: select "It failed".', 'In the "It failed" box, type only the line that starts with "Error" (no time stamp or session ID).'); Url = 'https://make.powerautomate.appsplatform.us/'; UrlConfig = '90161Z-flow-portal.txt'; Marker = '90161Z-T21-health-file-chosen.txt'; Estimate = 240; DoneText = ''; DoneLog = 'Confirmed by you: chose the file.'; Makes = @(); After = @('T21 Make the probe list r6', 'T21 Power Automate shows your connections r6'); Optional = $false; Help = ''; Hide = @('skip') }
$steps += @{ Name = 'T21 Import the health flow r5: connections'; Title = 'Finish the import of the health flow'; Dir = 'T21'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You finish the import of "90-161.Z probe health" and answer 2 questions. About 5 minutes.'; Kind = 'guide'; Guide = @('1. In each connection box, select the arrow on its right.', '2. Select your connection in the list.', '3. Select "Next".', '4. In the box "1 Site URL", type the address you typed in the RADE box "Site address".', '5. Select "Import".', '6. Wait for the line "Successfully imported".', '7. Select the solution "90-161.Z probe health".', '8. If its flow reads Off in the column "Status", select that flow.', '9. If you selected the flow, select "Turn on".', 'If a box has no connection: select "New connection" in that box.', 'If you selected "New connection": select "Create".', 'If a box has a "Refresh" button: select it.', 'If a sign-in window opens: sign in with your CAC.', 'If you see an error: wait 5 minutes, reload the Power Automate page, and try 1 more time.', 'If you cannot make a connection: select "It failed".', 'If the import fails: select "Download log file".', 'If the log file is saved: select "It failed".', 'In the "It failed" box, type only the line that starts with "Error" (no time stamp or session ID).'); Url = ''; UrlConfig = ''; Marker = '90161Z-T21-probe-imported.txt'; Estimate = 300; DoneText = ''; DoneLog = 'Confirmed by you: imported the health flow.'; Makes = @(); After = @('T21 Import the health flow r5: choose the file'); Optional = $false; Help = ''; Hide = @('skip'); Answers = @(@{ Key = 'mgmt-connector'; Prompt = 'Did the import page show a connection box for "Power Automate Management"?'; Kind = 'pick'; Choices = @('Yes, and I selected a connection', 'Yes, but no connection could be made', 'No such box') }, @{ Key = 'mgmt-premium'; Prompt = 'Did any page say a Premium licence is needed?'; Kind = 'pick'; Choices = @('No', 'Yes') }) }
