$steps += @{ Name = 'T21 Button flow by hand r5: make a solution'; Title = 'Make a solution for the button flow'; Dir = 'T21'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You make an empty solution "90-161.Z probe button" for one flow that you build by hand. About 4 minutes.'; Kind = 'guide'; Guide = @('1. Select "Open in browser" above.', '2. If Power Automate asks you to sign in: sign in with your CAC.', '3. On the left, select "Solutions" (it can be under "More").', '4. Select "New solution".', '5. In the box "Display name", type: 90-161.Z probe button', '6. In the box "Publisher", select any publisher in the list.', '7. Select "Create".', '8. Look at the list: the solution "90-161.Z probe button" must be there.', 'If Power Automate says the name is in use: the solution is already there; select "Cancel".', 'If you see an error: wait 5 minutes, reload the Power Automate page, and try 1 more time.', 'If a box or button is missing: select "It failed".', 'In the "It failed" box, type only the line that starts with "Error" (no time stamp or session ID).'); Url = 'https://make.powerautomate.appsplatform.us/'; UrlConfig = '90161Z-flow-portal.txt'; Marker = '90161Z-T21-button-solution.txt'; Estimate = 240; DoneText = ''; DoneLog = 'Confirmed by you: made the button solution.'; Makes = @(); After = @('T21 Power Automate shows your connections r6'); Optional = $false; Help = ''; Hide = @('skip') }
$steps += @{ Name = 'T21 Button flow by hand r5: make the flow'; Title = 'Make the button flow'; Dir = 'T21'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You make a new flow in the solution with the trigger "For a selected item". About 4 minutes.'; Kind = 'guide'; Guide = @('1. Select the solution "90-161.Z probe button".', '2. On the left, select "Objects".', '3. Select "New".', '4. Select "Automation".', '5. Select "Cloud flow".', '6. Select "Instant".', '7. In the box "Flow name", type: 90161Z T21 Probe Button hand r5', '8. In the search box of the trigger list, type: For a selected item', '9. Select the trigger "For a selected item" (SharePoint).', '10. Select "Create".', 'If you see an error: wait 5 minutes, reload the Power Automate page, and try 1 more time.', 'If no trigger "For a selected item" is listed: select "It failed".', 'In the "It failed" box, type only the line that starts with "Error" (no time stamp or session ID).'); Url = ''; UrlConfig = ''; Marker = '90161Z-T21-button-trigger.txt'; Estimate = 300; DoneText = ''; DoneLog = 'Confirmed by you: set the trigger.'; Makes = @(); After = @('T21 Button flow by hand r5: make a solution'); Optional = $false; Help = ''; Hide = @('skip') }
$steps += @{ Name = 'T21 Button flow by hand r5: site and list'; Title = 'Point the button flow at the test list'; Dir = 'T21'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You point the trigger at the probe list. About 2 minutes.'; Kind = 'guide'; Guide = @('1. In the box "Site Address", select the site whose address matches the one you typed in RADE.', '2. In the box "List Name", select "90161Z Probe".', '3. Look at the trigger: it must show the site and the list.', 'If you see an error: wait 5 minutes, reload the Power Automate page, and try 1 more time.', 'If the site or the list cannot be chosen: select "It failed".', 'If that site is not listed: select "Enter custom value".', 'If a box opens for the value: type the same address as in the RADE box "Site address".', 'In the "It failed" box, type only the line that starts with "Error" (no time stamp or session ID).'); Url = ''; UrlConfig = ''; Marker = '90161Z-T21-button-site-list.txt'; Estimate = 300; DoneText = ''; DoneLog = 'Confirmed by you: set the site and list.'; Makes = @(); After = @('T21 Button flow by hand r5: make the flow'); Optional = $false; Help = ''; Hide = @('skip') }
$steps += @{ Name = 'T21 Button flow by hand r5: the action'; Title = 'Add the action and save the button flow'; Dir = 'T21'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You add one action that writes a row, then save the flow. About 5 minutes.'; Kind = 'guide'; Guide = @('1. Under the trigger, select "New step".', '2. In the search box, type: Create item', '3. Select the SharePoint action "Create item".', '4. In the box "Site Address", select the site whose address matches the one you typed in RADE.', '5. In the box "List Name", select "90161Z Probe".', '6. In the box "Title", type: BTN-HAND', '7. Select "Save".', '8. Look at the top for the word "Saved".', 'If you see an error: wait 5 minutes, reload the Power Automate page, and try 1 more time.', 'If "Create item" is not listed: select "It failed".', 'If "Save" shows an error: select "It failed".', 'If that site is not listed: select "Enter custom value".', 'If a box opens for the value: type the same address as in the RADE box "Site address".', 'In the "It failed" box, type only the line that starts with "Error" (no time stamp or session ID).'); Url = ''; UrlConfig = ''; Marker = '90161Z-T21-button-action.txt'; Estimate = 300; DoneText = ''; DoneLog = 'Confirmed by you: saved the button flow.'; Makes = @(); After = @('T21 Button flow by hand r5: site and list'); Optional = $false; Help = ''; Hide = @('skip') }
$steps += @{ Name = 'T21 Button flow by hand r5: export the solution'; Title = 'Export the button flow solution'; Dir = 'T21'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You export the solution "90-161.Z probe button" and save the file in your Downloads folder. The next step reads it there. About 5 minutes.'; Kind = 'guide'; Guide = @('1. On the left, select "Solutions" (it can be under "More").', '2. Select the solution "90-161.Z probe button".', '3. In the top bar, select "Export solution".', '4. If the page offers "Publish": select it.', '5. Select "Next".', '6. Select "Unmanaged".', '7. Select "Export".', '8. When the page says the export is ready, select "Download".', '9. If the browser asks what to do with the file: select "Save".', '10. In File Explorer (press Windows+E), select "Downloads" on the left.', 'Look for the newest .zip file in that folder: it is the export.', 'If you see an error: wait 5 minutes, reload the Power Automate page, and try 1 more time.', 'If no .zip file is in Downloads: select "It failed".', 'In the "It failed" box, type only the line that starts with "Error" (no time stamp or session ID).'); Url = ''; UrlConfig = ''; Marker = '90161Z-T21-button-exported.txt'; Estimate = 300; DoneText = ''; DoneLog = 'Confirmed by you: exported the button solution.'; Makes = @(); After = @('T21 Button flow by hand r5: the action'); Optional = $false; Help = ''; Hide = @('skip') }
