$steps += @{ Name = 'T21 Use the list button r6'; Title = 'Use the button in the list'; Dir = 'T21'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You select a button in a list view that starts a test flow for that row. About 4 minutes.'; Kind = 'guide'; Guide = @('1. In the browser, select the tab "90-161.Z test page".', '2. Select "Open the list with the button".', '3. Look at the first row for a button "Run the test flow".', '4. In the first row, select "Run the test flow".', '5. Look at the panel that opened for a button "Run".', '6. Select "Run".', '7. If the panel asks you to continue or to allow a connection: select "Continue".', '8. Wait until the panel says the flow ran, or shows an error.', 'If you see an error: wait 5 minutes, reload the list page, and try 1 more time.'); Url = ''; UrlConfig = ''; Marker = '90161Z-T21-button-used.txt'; Estimate = 240; DoneText = 'I tried the button'; DoneLog = 'Confirmed by you: used the button.'; Makes = @(); After = @('T21 Make the list view with the flow button r6'); Optional = $false; Help = ''; Hide = @('failed', 'skip'); Answers = @(@{ Key = 'btn-show'; Prompt = 'What did the list show in each row?'; Kind = 'pick'; Choices = @('A button Run the test flow', 'No button', 'The plain list') }, @{ Key = 'btn-panel'; Prompt = 'What did the panel say after you selected Run?'; Kind = 'pick'; Choices = @('The flow ran', 'The flow was not found', 'An error', 'No panel opened') }) }
$steps += @{ Name = 'T24 Import the full solution r2: choose the file'; Title = 'Start the import of the full flows'; Dir = 'T24'; File = '90161Z-T24-full-flows-r2.zip'; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You start the import of the full 90-161.Z flows (every flow On). The next step finishes it. About 4 minutes.'; Kind = 'guide'; Guide = @('1. Select "Open in browser" above.', '2. If Power Automate asks you to sign in: sign in with your CAC.', '3. On the left, select "Solutions" (it can be under "More").', '4. Select "Import solution".', '5. Select "Browse".', '6. Select the box "File name".', '7. In the box "File name", press Ctrl+V (the file path is on the clipboard).', '8. Select "Open".', '9. Select "Next".', 'If the Open window closes before the file is chosen: select "Browse" again.', 'If the box "File name" is empty after Ctrl+V: press Ctrl+V again.', 'If you see an error: wait 5 minutes, reload the Power Automate page, and try 1 more time.', 'If the page refuses the file: select "It failed".', 'In the "It failed" box, type only the line that starts with "Error" (no time stamp or session ID).'); Url = 'https://make.powerautomate.appsplatform.us/'; UrlConfig = '90161Z-flow-portal.txt'; Marker = '90161Z-T24-file-chosen.txt'; Estimate = 240; DoneText = ''; DoneLog = 'Confirmed by you: chose the file.'; Makes = @(); After = @('T21 Power Automate shows your connections r6'); Optional = $false; Help = ''; Hide = @('skip') }
$steps += @{ Name = 'T24 Import the full solution r2: finish'; Title = 'Finish the import of the full flows'; Dir = 'T24'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You finish the import of the full flows. It upgrades the flows of the last rounds, so a message that they were replaced is normal. About 5 minutes.'; Kind = 'guide'; Guide = @('1. If the page says the solution already exists: select "Upgrade".', '2. In each connection box, select the arrow on its right.', '3. Select your connection in the list.', '4. Select "Next".', '5. If the box "1 Site URL" is empty: type the address you typed in the RADE box "Site address".', '6. If the box "2 Alert e-mail" is empty: type your work e-mail address (the one you use in Outlook).', '7. Select "Import".', '8. Wait for the line "Successfully imported".', 'If you see "The original workflow definition has been deactivated and replaced": go on.', 'If that message shows a button: select the button "Done" on that message.', 'If "Import" stays gray: in each box that already shows text, press Ctrl+A, Ctrl+X, then Ctrl+V.', 'If a box has no connection: select "New connection" in that box.', 'If you selected "New connection": select "Create".', 'If a box has a "Refresh" button: select it.', 'If a sign-in window opens: sign in with your CAC.', 'If the import fails: select "Download log file".', 'If you see an error: wait 5 minutes, reload the Power Automate page, and try 1 more time.', 'If the log file is saved: select "It failed".', 'In the "It failed" box, type only the line that starts with "Error" (no time stamp or session ID).'); Url = ''; UrlConfig = ''; Marker = '90161Z-T24-imported.txt'; Estimate = 300; DoneText = ''; DoneLog = 'Confirmed by you: imported the full solution.'; Makes = @(); After = @('T24 Import the full solution r2: choose the file'); Optional = $false; Help = ''; Hide = @('skip'); Answers = @(@{ Key = 'import-boxes'; Prompt = 'Before "Import" could be selected, which boxes did you have to cut and paste?'; Kind = 'pick'; Choices = @('None', 'Only the boxes that showed a list name', 'The list names and the 2 empty boxes', 'The connection boxes too') }, @{ Key = 'import-replaced'; Prompt = 'Did the page say that the original workflow definition was deactivated and replaced?'; Kind = 'pick'; Choices = @('Yes', 'No', 'I did not see') }) }
$steps += @{ Name = 'T24 Turn on all 6 flows r2'; Title = 'Turn on all 6 flows'; Dir = 'T24'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You check that all 6 flows read On and turn on any that do not. About 3 minutes.'; Kind = 'guide'; Guide = @('1. Select "Open in browser" above.', '2. On the left, select "Solutions" (it can be under "More").', '3. Select the solution "90-161.Z flows".', '4. Find F03 in the column "Status".', '5. Remember if it reads On or Off (the next card asks).', '6. Look at the other 5 flows: each must read On.', '7. If a flow reads Off: select that flow.', '8. If you selected a flow: select "Turn on".', 'If you see an error: wait 5 minutes, reload the Power Automate page, and try 1 more time.', 'If a flow will not turn on: select "It failed".', 'In the "It failed" box, type only the line that starts with "Error" (no time stamp or session ID).'); Url = 'https://make.powerautomate.appsplatform.us/'; UrlConfig = '90161Z-flow-portal.txt'; Marker = '90161Z-T24-flows-on.txt'; Estimate = 180; DoneText = ''; DoneLog = 'Confirmed by you: all flows On.'; Makes = @(); After = @('T24 Import the full solution r2: finish'); Optional = $false; Help = ''; Hide = @('skip'); Answers = @(@{ Key = 'f03-state'; Prompt = 'Before you changed anything, what did F03 read after the import?'; Kind = 'pick'; Choices = @('On', 'Off', 'I did not look') }) }
$steps += @{ Name = 'T24 Check the flows after the import r2'; Title = 'Check the flows and their connections'; Dir = 'T24'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You check that each of the 6 flows is On and that no flow shows a connection warning. About 3 minutes.'; Kind = 'guide'; Guide = @('1. Select "Open in browser" above.', '2. On the left, select "Solutions" (it can be under "More").', '3. Select the solution "90-161.Z flows".', '4. Count the flows that read On in the column "Status".', '5. Select the flow "90161Z F02 Next Review Due r3".', '6. Look at the card "Connections" for a yellow or red mark, or the words "Fix connection".', 'If you see an error: wait 5 minutes, reload the Power Automate page, and try 1 more time.', 'If the solution does not open: select "It failed".'); Url = 'https://make.powerautomate.appsplatform.us/'; UrlConfig = '90161Z-flow-portal.txt'; Marker = '90161Z-T24-flows-checked.txt'; Estimate = 180; DoneText = 'I checked the flows'; DoneLog = 'Confirmed by you: checked the flows and connections.'; Makes = @(); After = @('T24 Turn on all 6 flows r2'); Optional = $false; Help = ''; Hide = @('skip'); Answers = @(@{ Key = 'flows-on'; Prompt = 'How many of the 6 flows read On?'; Kind = 'pick'; Choices = @('6', '5', '4 or fewer') }, @{ Key = 'conn-warning'; Prompt = 'Did the card "Connections" show a warning?'; Kind = 'pick'; Choices = @('No warning', 'A warning or "Fix connection"', 'I found no card "Connections"') }) }
$steps += @{ Name = 'T24 Add a second owner to one flow r2'; Title = 'Add a second owner to one flow'; Dir = 'T24'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You add a person from your office as a second owner of one flow, so the flow keeps an owner if you leave. The round does not record the name. About 3 minutes.'; Kind = 'guide'; Guide = @('1. Select "Open in browser" above.', '2. On the left, select "Solutions" (it can be under "More").', '3. Select the solution "90-161.Z flows".', '4. Select the flow "90161Z F02 Next Review Due r3".', '5. Select "Share" at the top.', '6. In the box under "Owners", type the name of a person in your office who agreed to help.', '7. Select that person in the list.', 'If there is no "Share": on the card "Co-owners", select "Edit".', 'If a panel about connections opens: select "OK".', 'If you see an error: wait 5 minutes, reload the Power Automate page, and try 1 more time.', 'If the person cannot be added: select "It failed".', 'In the "It failed" box, type only the line that starts with "Error" (no name or session ID).'); Url = 'https://make.powerautomate.appsplatform.us/'; UrlConfig = '90161Z-flow-portal.txt'; Marker = '90161Z-T24-owner-added.txt'; Estimate = 180; DoneText = 'I added the owner'; DoneLog = 'Confirmed by you: added a second owner.'; Makes = @(); After = @('T24 Turn on all 6 flows r2'); Optional = $false; Help = ''; Answers = @(@{ Key = 'owner-added'; Prompt = 'Does the flow now show the person as an owner?'; Kind = 'pick'; Choices = @('Yes', 'No') }) }
$steps += @{ Name = 'T24 Full solution test, part 1 r2'; Title = 'Prepare the full flow test'; Dir = 'T24'; File = '90161Z-T24-full-solution-test-r2.ps1'; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 60; Args = '-Part 1'; Note = 'Signs in (CAC). Writes the PFM Settings rows (Test mode Yes) and fake rows, checks the first flow, then prepares two more. About 15 minutes.'; Kind = 'script'; Guide = @(); Url = ''; UrlConfig = ''; Marker = ''; Estimate = 900; DoneText = ''; DoneLog = ''; Makes = @(); After = @('T24 Turn on all 6 flows r2'); Optional = $false; Help = 'Send the results as they are. A FAIL here is a finding about a flow.'; Doing = 'Running the first part of the flow test.' }
$steps += @{ Name = 'T24 Run F02 once and F04 once r2'; Title = 'Run two of the flows by hand'; Dir = 'T24'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You run the review flow and the status report flow by hand. The status report sends one test e-mail to you. About 5 minutes.'; Kind = 'guide'; Guide = @('1. Select "Open in browser" above.', '2. On the left, select "Solutions" (it can be under "More").', '3. Select the solution "90-161.Z flows".', '4. Select the flow "90161Z F02 Next Review Due r3".', '5. Select "Run" at the top.', '6. Select the Back arrow at the top left to return to the solution.', '7. Select the flow "90161Z F04 Status Report r2".', '8. Select "Run" at the top.', '9. In the box "Send the report to (e-mail)", type your work e-mail address (the one in Outlook).', '10. Select "Run flow".', 'If a panel asks you to continue: select "Continue".', 'After the second run, wait 2 minutes.', 'If you see an error: wait 5 minutes, reload the Power Automate page, and try 1 more time.', 'If "Run" is missing or a run fails: select "It failed".', 'In the "It failed" box, type only the line that starts with "Error" (no time stamp or session ID).'); Url = 'https://make.powerautomate.appsplatform.us/'; UrlConfig = '90161Z-flow-portal.txt'; Marker = '90161Z-T24-ran-f02-f04.txt'; Estimate = 300; DoneText = ''; DoneLog = 'Confirmed by you: ran F02 and F04.'; Makes = @(); After = @('T24 Full solution test, part 1 r2'); Optional = $false; Help = ''; Hide = @('skip') }
$steps += @{ Name = 'T24 Full solution test, part 2 r2'; Title = 'Check what the two flows did'; Dir = 'T24'; File = '90161Z-T24-full-solution-test-r2.ps1'; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = '-Part 2'; Note = 'Signs in (CAC). Checks what the two flows did: review dates, review rows and the status-report log row. About 4 minutes.'; Kind = 'script'; Guide = @(); Url = ''; UrlConfig = ''; Marker = ''; Estimate = 240; DoneText = ''; DoneLog = ''; Makes = @(); After = @('T24 Run F02 once and F04 once r2'); Optional = $false; Help = 'Send the results as they are. A FAIL here is a finding about a flow.'; Doing = 'Running the second part of the flow test.' }
$steps += @{ Name = 'T24 Find the F04 e-mail r2'; Title = 'Find the test e-mail of the status report'; Dir = 'T24'; File = ''; Default = $true; AskParam = ''; AskPrompt = ''; ScreenOnly = ''; Minutes = 30; Args = ''; Note = 'You look for the test e-mail of the status report and answer 3 questions. About 3 minutes.'; Kind = 'guide'; Guide = @('1. Open Outlook (on this computer or in the browser).', '2. Select "Inbox".', '3. Look for an e-mail whose subject starts with "TEST MODE" (question 1).', '4. If it is not in the Inbox: open the folder "Junk Email".', '5. Open that e-mail.', '6. Look at its tables: each starts with the word "Step" and a number (question 2).', '7. Look at the To line (question 3).'); Url = ''; UrlConfig = ''; Marker = '90161Z-T24-email-looked.txt'; Estimate = 180; DoneText = 'I looked'; DoneLog = 'Confirmed by you: looked at the F04 e-mail.'; Makes = @(); After = @('T24 Full solution test, part 2 r2'); Optional = $false; Help = ''; Hide = @('failed', 'skip'); Answers = @(@{ Key = 'f04-found'; Prompt = 'Where is the F04 e-mail whose subject starts with TEST MODE?'; Kind = 'pick'; Choices = @('Inbox', 'Junk Email', 'Not found') }, @{ Key = 'f04-tables'; Prompt = 'Does it show 2 or more tables, each headed Step and a number?'; Kind = 'pick'; Choices = @('Yes', 'No'); ShowKey = 'f04-found'; ShowIn = @('Inbox', 'Junk Email') }, @{ Key = 'f04-to'; Prompt = 'Is the To line the alert address you typed (your own address)?'; Kind = 'pick'; Choices = @('Yes', 'No'); ShowKey = 'f04-found'; ShowIn = @('Inbox', 'Junk Email') }) }
